defmodule Orchestra.Rollout.Middleware do
  @behaviour Reactor.Middleware

  def reactor_init(reactor, _context), do: record(:reactor_init, "reactor") |> then(fn _ -> {:ok, reactor} end)
  def reactor_complete(reactor, _context), do: record(:reactor_complete, "reactor") |> then(fn _ -> {:ok, reactor} end)
  def reactor_error(reactor, _context), do: record(:reactor_error, "reactor") |> then(fn _ -> {:ok, reactor} end)

  def step_started(reactor, step, _context), do: record_step(step, :started) |> then(fn _ -> {:ok, reactor} end)
  def step_succeeded(reactor, step, _result, _context), do: record_step(step, :succeeded) |> then(fn _ -> {:ok, reactor} end)
  def step_failed(reactor, step, _error, _context), do: record_step(step, :failed) |> then(fn _ -> {:ok, reactor} end)

  defp record_step(step, event) do
    event_tag = case event do
      tag when is_atom(tag) -> tag
      {tag, _} -> tag
    end
    Orchestra.Rollout.Trace.record(event_tag, inspect(step.name))
  end

  defp record(event, label), do: Orchestra.Rollout.Trace.record(event, label)
end

